/** 
 * Returns a string representation of this OperationSetBasicTelephony instance including information that would permit to distinguish it among other instances when reading a log file.
 * @return a string representation of this operation set.
 */
public String toString(){
  try {
    return getClass().getSimpleName() + "-[dn=" + protocolProvider.getOurDisplayName()+ " addr=["+ protocolProvider.getRegistrarConnection().getAddressOfRecord()+ "]";
  } catch (ClassCastException | NullPointerException e) {
    return getClass().getSimpleName() + "-[dn=" + protocolProvider.getOurDisplayName()+ " addr=[unknown]";
  }
}
